require_once __DIR__.'/../includes/auth_redirect.php';startPortalSession('admin');if(!isset($_SESSION['user_id'])||($_SESSION['role']??'')!=='admin'){header('Location: login.php');exit;}require_once '../includes/config.php';require_once '../includes/security.php';require_once '../includes/db.php';require_once '../includes/innovation.php';require_once '../includes/customer_email_notifications.php';ensureInnovationSchema($conn);$id=(int)($_GET['order_id']??$_POST['order_id']??0);$o=$conn->query("SELECT * FROM orders WHERE id=$id LIMIT 1")->fetch_assoc();if(!$o){exit('Order not found');}$msg='';if(($_SERVER['REQUEST_METHOD']??'')==='POST'){if(!portalCsrfValid($_POST['portal_csrf_token']??null)){http_response_code(403);exit('Session expired. Refresh the page and try again.');} $st=$_POST['status']??'pending';if(!in_array($st,['pending','out_for_delivery','delivered'],true))$st='pending';$notes=trim((string)($_POST['notes']??''));$file='';if(!empty($_FILES['proof']['name'])){$ext=strtolower(pathinfo($_FILES['proof']['name'],PATHINFO_EXTENSION));if(in_array($ext,['jpg','jpeg','png','webp'],true)){$dir=__DIR__.'/../uploads/delivery';if(!is_dir($dir))mkdir($dir,0775,true);$file='delivery_'.$id.'_'.date('YmdHis').'.'.$ext;move_uploaded_file($_FILES['proof']['tmp_name'],$dir.'/'.$file);}}$uid=(int)$_SESSION['user_id'];$s=$conn->prepare("INSERT INTO delivery_tracking(order_id,status,proof_file,notes,updated_by) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status),proof_file=IF(VALUES(proof_file)<>'',VALUES(proof_file),proof_file),notes=VALUES(notes),updated_by=VALUES(updated_by)");$s->bind_param('isssi',$id,$st,$file,$notes,$uid);$s->execute();$s->close();customerEmailSendOnce($conn,$id,'delivery-'.$id.'-'.$st.'-'.date('YmdHi'),'Delivery update: '.ucwords(str_replace('_',' ',$st)),'Your delivery status is now '.ucwords(str_replace('_',' ',$st)).($notes?". Note: $notes":'.'));$msg='Delivery status updated.';}
